import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"Watermark 水印","description":"","frontmatter":{},"headers":[],"relativePath":"components/watermark.md","filePath":"components/watermark.md","lastUpdated":1791177194000}`),l={name:`components/watermark.md`};function u(a,c,l,u,d,f){let p=e(`XhDemo`);return t(),i(`div`,null,[c[0]||=s(`<h1 id="watermark-水印" tabindex="-1">Watermark 水印 <a class="header-anchor" href="#watermark-水印" aria-label="Permalink to “Watermark 水印”">​</a></h1><p>在内容区域上重复显示文字或图片水印。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/watermark" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/watermark.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/watermark" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/watermark" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/watermark.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>为内容添加文字水印</p>`,5),r(p,{src:`watermark/01-basic`}),c[1]||=s(`<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to “组件结构”">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;watermark&quot;</code>：<strong><code>root</code></strong> · <code>content</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><h3 id="多行水印" tabindex="-1">多行水印 <a class="header-anchor" href="#多行水印" aria-label="Permalink to “多行水印”">​</a></h3><p>显示归属和时间信息</p>`,6),r(p,{src:`watermark/02-multi-line`}),c[2]||=o(`h3`,{id:`外观`,tabindex:`-1`},[n(`外观 `),o(`a`,{class:`header-anchor`,href:`#外观`,"aria-label":`Permalink to “外观”`},`​`)],-1),c[3]||=o(`p`,null,`设置角度、间距、字号和透明度`,-1),r(p,{src:`watermark/03-appearance`}),c[4]||=o(`h3`,{id:`自定义颜色`,tabindex:`-1`},[n(`自定义颜色 `),o(`a`,{class:`header-anchor`,href:`#自定义颜色`,"aria-label":`Permalink to “自定义颜色”`},`​`)],-1),c[5]||=o(`p`,null,`设置水印前景色`,-1),r(p,{src:`watermark/04-custom-color`}),c[6]||=o(`h3`,{id:`图片地址`,tabindex:`-1`},[n(`图片地址 `),o(`a`,{class:`header-anchor`,href:`#图片地址`,"aria-label":`Permalink to “图片地址”`},`​`)],-1),c[7]||=o(`p`,null,`同源或放行了跨域的地址先取回再印出剪影`,-1),r(p,{src:`watermark/05-image-url`}),c[8]||=o(`h3`,{id:`全屏水印`,tabindex:`-1`},[n(`全屏水印 `),o(`a`,{class:`header-anchor`,href:`#全屏水印`,"aria-label":`Permalink to “全屏水印”`},`​`)],-1),c[9]||=o(`p`,null,`固定铺满整个视口，压在页面一切内容之上`,-1),r(p,{src:`watermark/06-fullscreen`}),c[10]||=s(`<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to “设计指引”">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h3><ul><li>标记内部数据、预览稿或样例内容。</li><li>在导出或截图内容中保留归属信息。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to “何时不用”">​</a></h3><ul><li>水印不能替代访问控制或数据脱敏。</li><li>装饰纹理应使用背景样式。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li>支持单行、多行文字和图片水印。图片可以是 <code>data:image/</code> 内联图片，也可以是 http(s)、<code>blob:</code> 或相对路径的地址：地址形式的图片按匿名跨域取回、画进 canvas 转成内联图片再印，取回之前只印文字；跨域地址须带 <code>Access-Control-Allow-Origin</code> 放行，否则浏览器拒载或 canvas 被污染，这张图不印并报一条诊断，文字照印。<code>javascript:</code> 等其余协议一律不收。</li><li>支持角度、间距、字号、透明度和字体配置。</li><li>水印不拦截指针事件，也不影响文本选择。</li><li>深浅主题下自动使用对应的前景色。</li><li>防篡改：删掉水印的根节点会被原位放回，改写它的 <code>data-scope</code> / <code>data-part</code> / <code>data-state</code> / <code>data-fullscreen</code> 或内联的图样变量会被改回当下 props 算出的值；组件卸载时先撤掉观察，正常卸载不受影响。它防的是直接动 DOM 的抹除，覆盖样式表、截图后处理之类防不住。</li><li><code>fullscreen</code> 全屏档：印子固定铺满整个视口，压在页面一切内容之上（含对话框与轻提示），页面滚动时原地不动；此时 root 不再建层叠上下文，放在页面任何位置都一样。祖先带 transform / filter 时 fixed 会被困在那个祖先里，全屏水印要放在没有这类祖先的地方。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to “组合”">​</a></h3><ul><li>可包裹<a href="./table">表格</a>、<a href="./card">卡片</a>或页面内容区。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li>保持水印可见，但不要干扰正文阅读。</li><li>需要追溯时包含用户、时间或文档编号。</li><li>图片水印优先使用轮廓清晰的单色图形。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to “反模式”">​</a></h3><ul><li>不要把水印当作安全边界。</li><li>不要使用过高的不透明度。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to “产物”">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-watermark&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhWatermarkContent</code> <code>XhWatermarkRoot</code></td></tr><tr><td>状态机</td><td><code>watermarkMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/watermark.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to “Props”">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>fontFamily</code></td><td><code>string</code></td><td></td><td>印文字使用的字体，默认 <code>sans-serif</code>。 图样是一张用作遮罩的 SVG，无法获取页面中的字体，因此需要在这里把字体名写全 （例如 <code>&#39;PingFang SC, sans-serif&#39;</code>）；书写的字体在运行环境中不存在时由平台自行回退。</td></tr><tr><td><code>fontSize</code></td><td><code>number</code></td><td></td><td>字号，单位像素，默认 14。</td></tr><tr><td><code>fullscreen</code></td><td><code>boolean</code></td><td></td><td>全屏档：印子固定铺满整个视口，压在页面一切内容之上（含对话框与轻提示），不随 root 的盒子走， 页面滚动时原地不动；root 本身不再建层叠上下文。默认 false。</td></tr><tr><td><code>gap</code></td><td><code>number</code></td><td></td><td>两块图样之间的空白，单位像素，默认 24。</td></tr><tr><td><code>image</code></td><td><code>string</code></td><td></td><td>印在文字上方的图片：<code>data:image/</code> 开头的内联图片，或 http(s)、相对路径与 <code>blob:</code> 地址。 图样用作遮罩，遮罩只取图样的透明度：印出的是该图的剪影，颜色仍由 <code>--xh-watermark-fg</code> 提供。 地址形式的图片先按匿名跨域取回、画进 canvas 转成内联图片再印：SVG 当图片用时自己取不到外部资源。 跨域的地址须带 <code>Access-Control-Allow-Origin</code> 放行，否则取不回或 canvas 被污染，这张图不印并报一条诊断， 文字照印；取回之前只印文字。其余协议（如 <code>javascript:</code>）一律不收。</td></tr><tr><td><code>imageSize</code></td><td><code>WatermarkImageSize</code></td><td></td><td>图片的像素尺寸，默认 64 × 64。</td></tr><tr><td><code>opacity</code></td><td><code>number</code></td><td></td><td>印记的深浅，0 到 1，默认 0.15。</td></tr><tr><td><code>rotate</code></td><td><code>number</code></td><td></td><td>倾斜角度，单位度，默认 -22。</td></tr><tr><td><code>text</code></td><td><code>string | string[]</code></td><td></td><td>水印文字。提供数组即多行，单个字符串中的换行同样断行； 空白行会被去除：它只使图样增高，不印出任何内容。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to “状态”">​</a></h3><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>IMAGE.LOADED</code> · <code>IMAGE.CLEAR</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to “connect API”">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>lines</code></td><td><code>readonly string[]</code></td><td>归一化后的文字行；没有可印的文字时为空数组。</td></tr><tr><td><code>tile</code></td><td><code>WatermarkTile</code></td><td>图样尺寸，即平铺步距；没有图样时宽高都是 0。</td></tr><tr><td><code>image</code></td><td><code>string</code></td><td>图样的 data URI；没有图样时为空串。</td></tr><tr><td><code>state</code></td><td><code>WatermarkState</code></td><td></td></tr><tr><td><code>fullscreen</code></td><td><code>boolean</code></td><td>全屏档：印子固定铺满视口。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to “无障碍”">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to “键盘”">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to “样式参考”">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to “皮肤”">​</a></h3><p><code>@xihan-ui/styles/watermark.css</code> 按 <code>[data-scope=&quot;watermark&quot;][data-part=&quot;root&quot;]</code> 部件选择器书写，发布产物以挂载类 <code>.xh-scope-watermark</code> 代替其中的 data-scope（特异性相同），位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>，部件选择器照常可用。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to “CSS 变量”">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-watermark-fg</code></td><td><code>root</code></td><td><code>background-color</code></td><td><code>state=ready</code></td><td><code>--xh-fg-muted</code></td><td>watermark 的 root 部件 background-color 覆盖槽。</td></tr><tr><td><code>--xh-watermark-image</code></td><td><code>root</code></td><td><code>-webkit-mask-image</code><br><code>mask-image</code></td><td><code>state=ready</code></td><td><code>none</code></td><td>watermark 的 root 部件 -webkit-mask-image、mask-image 覆盖槽。</td></tr><tr><td><code>--xh-watermark-layer</code></td><td><code>root</code></td><td><code>z-index</code></td><td><code>fullscreen</code><br><code>state=ready</code></td><td><code>--xh-layer-tooltip</code></td><td>watermark 的 root 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-watermark-tile</code></td><td><code>root</code></td><td><code>-webkit-mask-size</code><br><code>mask-size</code></td><td><code>state=ready</code></td><td><code>auto</code></td><td>watermark 的 root 部件 -webkit-mask-size、mask-size 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to “动效”">​</a></h3><p>本组件皮肤不含过渡与关键帧，也没有脚本驱动的动效：状态一变，外观立即到位。</p>`,38)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};